frappe.ui.form.on('Leave Application', {
    employee: function(frm) {
        set_valid_leave_types(frm);
    },
    posting_date: function(frm) {
        set_valid_leave_types(frm);
    },
    onload: function(frm) {
        set_valid_leave_types(frm);
    }
});

function set_valid_leave_types(frm) {
    if (!frm.doc.employee) {
        console.log("No employee set yet");
        return;
    }

    frappe.call({
        method: "leave_types_not_expired",
        args: {
            employee: frm.doc.employee,
            date: frm.doc.posting_date || frappe.datetime.get_today()
        },
        callback: function(r) {
            console.log("valid_types received:", r.message);

            let valid_types = r.message || [];

            if (valid_types.length === 0) {
                console.warn("No valid leave types found for this employee/date");
            }

            frm.set_query('leave_type', function() {
                return {
                    filters: [["Leave Type", "name", "in", valid_types]]
                };
            });

            // Force refresh so the query takes effect immediately if field already has focus
            frm.refresh_field('leave_type');
        }
    });
}

cur_frm.add_fetch("parent_item_group", "custom_main_code", "custom_main_code");


frappe.ui.form.on('Item Group', {
    async validate(frm) {

        if (!frm.doc.custom_sub_code) {
            return;
        }

        let code = String(frm.doc.custom_sub_code);

        // Must be exactly 3 digits
        if (!/^\d{3}$/.test(code)) {
            frappe.throw(__('Sub Code must be exactly 3 digits (e.g. 001, 123, 999).'));
        }

        let duplicate = await frappe.db.get_list('Item Group', {
            filters: {
                parent_item_group: frm.doc.parent_item_group,
                custom_sub_code: frm.doc.custom_sub_code,
                name: ['!=', frm.doc.name]
            },
            fields: ['name'],
            limit: 1
        });

        if (duplicate.length) {
            frappe.throw(__('Sub Code already exists under this Parent Item Group.'));
        }
    }
});

frappe.ui.form.on("Item Group", {

    before_save: function(frm) {

        // Only for child Item Groups
        if (frm.doc.is_group) {
            return;
        }

        // Parent Item Group must exist
        if (!frm.doc.parent_item_group) {
            return;
        }

        // Only fetch if Main Code is not already set
        if (
            frm.doc.custom_main_code &&
            String(frm.doc.custom_main_code).trim() !== ""
        ) {
            return;
        }

        frappe.call({
            method: "frappe.client.get_value",
            args: {
                doctype: "Item Group",
                filters: {
                    name: frm.doc.parent_item_group
                },
                fieldname: "custom_main_code"
            },
            async: false,

            callback: function(r) {

                if (r.message && r.message.custom_main_code) {

                    frm.set_value(
                        "custom_main_code",
                        r.message.custom_main_code
                    );
                }
            }
        });
    }
});

frappe.ui.form.on('Item', {
    item_group: function (frm) {
        if (!frm.doc.item_group ) return;
        generate_item_code_from_existing(frm);
    },

    validate: function (frm) {
        if (!frm.doc.item_name) {
            frappe.throw(__('Please enter Item Name'));
        }
	if (frm.doc.item_name === frm.doc.item_code) {
	    frm.set_value("item_name", frm.doc.item_name || ""); // reset if it accidentally matched
	}

	// --- Auto set Description if empty or same as item_code ---
        if (!frm.doc.description || frm.doc.description === frm.doc.item_code) {
            frm.set_value("description", frm.doc.item_name);
        }


        if (!frm.doc.item_code && frm.doc.item_group) {
            frappe.validated = false;
            generate_item_code_from_existing(frm, true, function () {
		// Once generated, also update description if still empty or same as code
                if (!frm.doc.description || frm.doc.description === frm.doc.item_code) {
                    frm.set_value("description", frm.doc.item_name);
                }
                frappe.validated = true;
                frm.save();
            });
        }
    }
});

function generate_item_code_from_existing(frm, is_sync = false, callback) {
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Item",
            fields: ["item_code"],
            filters: { item_group: frm.doc.item_group },
            order_by: "item_code desc",
            limit_page_length: 1
        },
        async: !is_sync,
        callback: function (res) {
            if (res.message && res.message.length > 0) {
                // --- Existing items found: increment the last code ---
                let last_code = res.message[0].item_code;
                let parts = last_code.split("-");
                if (parts.length === 3) {
                    let main = parts[0];
                    let sub = parts[1];
                    let last_number = parseInt(parts[2]) || 0;
                    let next_number = last_number + 1;
                    let next_code = `${main}-${sub}-${String(next_number).padStart(4, '0')}`;

                    frm.set_value("item_code", next_code);
                    frm.set_df_property("item_code", "read_only", 1);
                    frm.refresh_field("item_code");
                }
                if (callback) callback();
            } else {
                // --- No items in this group: fetch main_code and sub_code from Item Group ---
                frappe.call({
                    method: "frappe.client.get_value",
                    args: {
                        doctype: "Item Group",
                        filters: { name: frm.doc.item_group },
                        fieldname: ["custom_main_code", "custom_sub_code"]
                    },
                    callback: function (r) {
                        if (r.message) {
                            // --- Pad main_code and sub_code ---
                            let main = String(r.message.custom_main_code || "0").padStart(2, '0');
                            let sub = String(r.message.custom_sub_code || "0").padStart(3, '0');

                            let next_code = `${main}-${sub}-0001`;
                            frm.set_value("item_code", next_code);
                            frm.set_df_property("item_code", "read_only", 1);
                            frm.refresh_field("item_code");
                        }
                        if (callback) callback();
                    }
                });
            }
        }
    });
}

frappe.ui.form.on('Item', {
    onload: function(frm) {
        frm.set_query('item_group', function() {
            return {
                filters: {
                    "is_group": 0
                }
            };
        });
         // If this Item was duplicated, generate a new Item Code
        if (frm.is_new() && frm.doc.__islocal && frm.doc.item_group) {
            generate_item_code_from_existing(frm);
        }
    }
});

frappe.ui.form.on('Date Converter', {
    date_gc: function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        const gcDate = row.date_gc;

        if (gcDate) {
            // Split the date (YYYY-MM-DD) into numbers
            const [year, month, day] = gcDate.split("-").map(Number);

            // Convert Gregorian → Ethiopian (assuming toEC is defined globally)
            const [ecYear, ecMonth, ecDay] = toEC([year, month, day]);

            // Format as DD/MM/YYYY
            const formattedEC = `${ecDay < 10 ? '0' : ''}${ecDay}/${ecMonth < 10 ? '0' : ''}${ecMonth}/${ecYear}`;

            frappe.model.set_value(cdt, cdn, 'date_ec', formattedEC);
        }
    },

    date_ec: function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        const ecDate = row.date_ec;

        if (ecDate) {
            // Split the date (DD/MM/YYYY)
            const [day, month, year] = ecDate.split("/").map(Number);

            // Convert Ethiopian → Gregorian
            const [gcYear, gcMonth, gcDay] = toGC([year, month, day]);

            // Format as YYYY-MM-DD
            const formattedGC = `${gcYear}-${gcMonth < 10 ? '0' : ''}${gcMonth}-${gcDay < 10 ? '0' : ''}${gcDay}`;

            frappe.model.set_value(cdt, cdn, 'date_gc', formattedGC);
        }
    }
});

