frappe.ui.form.on('Employee External Work History', {
    custom_from_date: function(frm, cdt, cdn) {
        updateECAndCalculate(frm, cdt, cdn, 'custom_from_date');
    },
    custom_to_date: function(frm, cdt, cdn) {
        updateECAndCalculate(frm, cdt, cdn, 'custom_to_date');
    },
    custom_from_date_ec: function(frm, cdt, cdn) {
        updateGCAndCalculate(frm, cdt, cdn, 'custom_from_date_ec');
    },
    custom_to_date_ec: function(frm, cdt, cdn) {
        updateGCAndCalculate(frm, cdt, cdn, 'custom_to_date_ec');
    },
    external_work_history_remove: function(frm) {
        calculate_external_total(frm);
    }
});

function updateECAndCalculate(frm, cdt, cdn, field) {
    let row = locals[cdt][cdn];
    if (!row[field]) return;

    const [year, month, day] = toEC(row[field].split("-").map(Number));
    row[field + "_ec"] = `${day < 10 ? '0' : ''}${day}/${month < 10 ? '0' : ''}${month}/${year}`;
    frm.refresh_field("external_work_history");

    // run experience calculation after GC date exists
    calculate_experience(frm, cdt, cdn);
    calculate_external_total(frm);
}

function updateGCAndCalculate(frm, cdt, cdn, field) {
    let row = locals[cdt][cdn];
    if (!row[field]) return;

    const [day, month, year] = row[field].split("/").map(Number);
    const [gcYear, gcMonth, gcDay] = toGC([year, month, day]);
    const gcField = field.replace("_ec", "");
    row[gcField] = `${gcYear}-${gcMonth < 10 ? '0' : ''}${gcMonth}-${gcDay < 10 ? '0' : ''}${gcDay}`;
    frm.refresh_field("external_work_history");

    // run experience calculation after GC date exists
    calculate_experience(frm, cdt, cdn);
    calculate_external_total(frm);
}

function calculate_experience(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    if (!row.custom_from_date || !row.custom_to_date) return;

    let fromDate = new Date(row.custom_from_date);
    let toDate = new Date(row.custom_to_date);
    if (isNaN(fromDate) || isNaN(toDate)) return;

    let years = toDate.getFullYear() - fromDate.getFullYear();
    let months = toDate.getMonth() - fromDate.getMonth();
    let days = toDate.getDate() - fromDate.getDate();

    if (days < 0) {
        months -= 1;
        days += new Date(toDate.getFullYear(), toDate.getMonth(), 0).getDate();
    }
    if (months < 0) {
        years -= 1;
        months += 12;
    }

    let englishExp = `${years} years ${months} months ${days} days`;
    let amharicExp = `${years} ዓመት ${months} ወር ${days} ቀን`;

    frappe.model.set_value(cdt, cdn, "total_experience", englishExp);
    frappe.model.set_value(cdt, cdn, "custom_total_experience_amharic", amharicExp);
}

function calculate_external_total(frm) {
    let totalYears = 0, totalMonths = 0, totalDays = 0;

    (frm.doc.external_work_history || []).forEach(row => {
        if (!row.custom_from_date || !row.custom_to_date) return;

        let fromDate = new Date(row.custom_from_date);
        let toDate = new Date(row.custom_to_date);
        if (isNaN(fromDate) || isNaN(toDate)) return;

        let years = toDate.getFullYear() - fromDate.getFullYear();
        let months = toDate.getMonth() - fromDate.getMonth();
        let days = toDate.getDate() - fromDate.getDate();

        if (days < 0) {
            months -= 1;
            days += new Date(toDate.getFullYear(), toDate.getMonth(), 0).getDate();
        }
        if (months < 0) {
            years -= 1;
            months += 12;
        }

        totalYears += years;
        totalMonths += months;
        totalDays += days;
    });

    // Normalize totals
    totalMonths += Math.floor(totalDays / 30);
    totalDays = totalDays % 30;
    totalYears += Math.floor(totalMonths / 12);
    totalMonths = totalMonths % 12;

    frm.set_value("custom_external_total_experience_english", `${totalYears} years ${totalMonths} months ${totalDays} days`);
    frm.set_value("custom_external_total_experience_amharic", `${totalYears} ዓመት ${totalMonths} ወር ${totalDays} ቀን`);
}
// Internal Work History
frappe.ui.form.on('Employee Internal Work History', {
    custom_from_date_gc: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (row.custom_from_date_gc) {
            const [year, month, day] = toEC(row.custom_from_date_gc.split("-").map(Number));
            row.custom_from_date_ec = `${day < 10 ? '0' : ''}${day}/${month < 10 ? '0' : ''}${month}/${year}`;
            frm.refresh_field("internal_work_history");
        }
        calculate_internal_experience(frm, cdt, cdn);
        calculate_internal_total(frm);
    },
    custom_from_date_ec: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (row.custom_from_date_ec) {
            const [day, month, year] = row.custom_from_date_ec.split("/").map(Number);
            const [gcYear, gcMonth, gcDay] = toGC([year, month, day]);
