function calculate_internal_experience(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    if (!row.custom_from_date_gc || !row.custom_to_date_gc) return;

    let fromDate = new Date(row.custom_from_date_gc);
    let toDate = new Date(row.custom_to_date_gc);
    if (isNaN(fromDate) || isNaN(toDate)) return;

    let years = toDate.getFullYear() - fromDate.getFullYear();
    let months = toDate.getMonth() - fromDate.getMonth();
    let days = toDate.getDate() - fromDate.getDate();

    if (days < 0) {
        months -= 1;
        days += new Date(toDate.getFullYear(), toDate.getMonth(), 0).getDate();
    }
    if (months < 0) {
        years -= 1;
        months += 12;
    }

    let englishExp = `${years} years ${months} months ${days} days`;
    let amharicExp = `${years} ዓመት ${months} ወር ${days} ቀን`;

    frappe.model.set_value(cdt, cdn, "custom_total_experiance_in_english", englishExp);
    frappe.model.set_value(cdt, cdn, "custom_total_experiance_in_amharic", amharicExp);
}

// Internal total calculation across all rows
function calculate_internal_total(frm) {
    let totalYears = 0, totalMonths = 0, totalDays = 0;

    (frm.doc.internal_work_history || []).forEach(row => {
        if (!row.custom_from_date_gc || !row.custom_to_date_gc) return;

        let fromDate = new Date(row.custom_from_date_gc);
        let toDate = new Date(row.custom_to_date_gc);
        if (isNaN(fromDate) || isNaN(toDate)) return;

        let years = toDate.getFullYear() - fromDate.getFullYear();
        let months = toDate.getMonth() - fromDate.getMonth();
        let days = toDate.getDate() - fromDate.getDate();

        if (days < 0) {
            months -= 1;
            days += new Date(toDate.getFullYear(), toDate.getMonth(), 0).getDate();
        }
        if (months < 0) {
            years -= 1;
            months += 12;
        }

        totalYears += years;
        totalMonths += months;
        totalDays += days;
    });

    // Normalize totals
    totalMonths += Math.floor(totalDays / 30);
    totalDays %= 30;
    totalYears += Math.floor(totalMonths / 12);
    totalMonths %= 12;

    frm.set_value("custom_internal_total_experience_english", `${totalYears} years ${totalMonths} months ${totalDays} days`);
    frm.set_value("custom_internal_total_experience_amharic", `${totalYears} ዓመት ${totalMonths} ወር ${totalDays} ቀን`);
}
