function validate_no_overlap(frm, cdt, cdn, child_table) {
    let row = locals[cdt][cdn];
    if (!row.custom_from_date || !row.custom_to_date) return true;

    let fromDate = frappe.datetime.str_to_obj(row.custom_from_date);
    let toDate = frappe.datetime.str_to_obj(row.custom_to_date);

    if (!fromDate || !toDate) return true;

    let rows = frm.doc[child_table] || [];

    for (let r of rows) {
        if (r.name === row.name) continue;
        if (!r.custom_from_date || !r.custom_to_date) continue;

        let rFrom = frappe.datetime.str_to_obj(r.custom_from_date);
        let rTo = frappe.datetime.str_to_obj(r.custom_to_date);

        if (!rFrom || !rTo) continue;

        if (fromDate <= rTo && toDate >= rFrom) {
            frappe.msgprint(__('Date range overlaps within the same table.'));
            frappe.model.set_value(cdt, cdn, "custom_from_date", null);
            frappe.model.set_value(cdt, cdn, "custom_to_date", null);
            frm.refresh_field(child_table);
            return false;
        }
    }

    return true;
}

