            if (!duration) return { years: 0, months: 0, days: 0 };
            let m = duration.match(/\d+/g) || [0, 0, 0];
            return {
                years: parseInt(m[0]) || 0,
                months: parseInt(m[1]) || 0,
                days: parseInt(m[2]) || 0
            };
        }

        let internal = parseDuration(frm.doc.custom_internal_total_experience_english);
        let external = parseDuration(frm.doc.custom_external_total_experience_english);

        let totalYears = internal.years + external.years;
        let totalMonths = internal.months + external.months;
        let totalDays = internal.days + external.days;

        // Normalize → 30 days = 1 month, 12 months = 1 year
        totalMonths += Math.floor(totalDays / 30);
        totalDays = totalDays % 30;
        totalYears += Math.floor(totalMonths / 12);
        totalMonths = totalMonths % 12;

        // English
        let finalEnglish = `${totalYears} years ${totalMonths} months ${totalDays} days`;

        // Amharic
        let finalAmharic = `${totalYears} አመት ${totalMonths} ወር ${totalDays} ቀን`;

        frm.set_value("custom_grand_total_experience_english", finalEnglish);
        frm.set_value("custom_grand_total_experience_amharic", finalAmharic);
    }
});


