//make change basic salary to words


frappe.ui.form.on('Employee', {
    custom_basic_salary: function (frm) {
        var inFigureValue = parseFloat(frm.doc.custom_basic_salary);
        var hasCents = inFigureValue % 1 !== 0;

        // Function to convert a number to words
        function numberToWords(num) {
            var units = ['', 'አንድ', 'ሁለት', 'ሶስት', 'አራት', 'አምስት', 'ስድስት', 'ሰባት', 'ሰምንት', 'ዘጠኝ'];
            var teens = ['አስር', 'አስራ አንድ', 'አስራ ሁለት', 'አስራ ሶስት', 'አስራ አራት', 'አስራ አምስት', 'አስራ ስድስት', 'አስራ ሰባት', 'አስራ ሰምንት', 'አስራ ዘጠኝ'];
            var tens = ['', '', 'ሃያ', 'ሰላሳ', 'አርባ', 'ሃምሳ', 'ስልሳ', 'ሰባ', 'ሰማኒያ', 'ዘጠና'];

            if (num < 10) {
                return units[num];
            } else if (num < 20) {
                return teens[num - 10];
            } else if (num < 100) {
                return tens[Math.floor(num / 10)] + ' ' + units[num % 10];
            } else if (num < 1000) {
                return units[Math.floor(num / 100)] + ' መቶ ' + numberToWords(num % 100);
            } else if (num < 1000000) {
                return numberToWords(Math.floor(num / 1000)) + ' ሺ ' + numberToWords(num % 1000);
            } else if (num < 1000000000) {
                return numberToWords(Math.floor(num / 1000000)) + ' ሚሊዮን ' + numberToWords(num % 1000000);
            } else if (num < 1000000000000) {
                return numberToWords(Math.floor(num / 1000000000)) + ' ቢሊዮን ' + numberToWords(num % 1000000000);
            } else {
                return 'Number out of range';
            }
        }

        // Convert the number to words
        var inWordValue = numberToWords(Math.floor(inFigureValue));

        if (!hasCents) {
            // If no cents, set the value directly
            frm.set_value('custom_slary_in_words', inWordValue + " ብር");
        } else {
            // If there are cents, set the value in the 'in_word' field including cents part
            var centsValue = Math.round((inFigureValue % 1) * 100);
            var centsWord = numberToWords(centsValue) + " ሳንቲም";
            frm.set_value('custom_slary_in_words', inWordValue + " ብር ከ " + centsWord);
        }
    }
});




