// Unified update function for child table
function update_all(frm, cdt, cdn) {
    var row = locals[cdt][cdn];

    // Step 1: Update d6 based on time_option and data_4
    updateRate(frm, cdt, cdn);

    // Step 2: Update d5, d4, d7
    calculate_row_values(frm, cdt, cdn);
}

// Calculates d5, d4, d7 for a row
function calculate_row_values(frm, cdt, cdn) {
    let row = locals[cdt][cdn];

    // d5 = data_6 - data_5 (in hours)
    if (row.data_5 && row.data_6) {
        let start = moment(row.data_5, "HH:mm:ss");
        let end = moment(row.data_6, "HH:mm:ss");
    
        // FIX: handle next-day time
        if (end.isBefore(start)) {
            end.add(1, 'day');
        }
    
        let diff = moment.duration(end.diff(start)).asHours();
        row.d5 = diff > 0 ? diff : 0;
    }

    // d4 = salary / d3
    if (frm.doc.salary && row.d3) {
        row.d4 = flt(frm.doc.salary) / flt(row.d3);
    }

    // d7 = d4 * d5 * d6
    if (row.d4 && row.d5 && row.d6) {
        row.d7 = flt(row.d4) * flt(row.d5) * flt(row.d6);
    }

    frappe.model.set_value(cdt, cdn, "d5", row.d5);
    frappe.model.set_value(cdt, cdn, "d4", row.d4);
    frappe.model.set_value(cdt, cdn, "d7", row.d7);

    // Update parent total
    calculate_total(frm);
}
