        else if (day_type === "የህዝብ በዓላት") rate = 2.5;
    } else if (time_option === "ክምሽቱ 4:00 - ንጋቱ 12:00") {
        if (day_type === "መደበኛ የስራ ቀናት") rate = 1.75;
        else if (day_type === "የእረፍት ቀናት") rate = 2;
