        }
    }
});

// Helper to fetch tax slabs dynamically from Employee Income Tax Slab DocType
function fetch_tax_slabs_and_calculate(frm) {
    if (cached_tax_slabs) {
        recalculate_all_rows(frm);
        return;
    }

    frappe.db.get_list('Employee Income Tax Slab', {
        fields: ['name'],
        limit: 1
    }).then(records => {
        if (records && records.length > 0) {
            frappe.db.get_doc('Employee Income Tax Slab', records[0].name).then(doc => {
                // Cache child table rows
                cached_tax_slabs = doc.tax_slab_table || doc.employee_income_tax_slab_table || [];
                recalculate_all_rows(frm);
            });
        } else {
            frappe.msgprint(__('No Employee Income Tax Slab found. Tax calculations will default to 0.'));
            recalculate_all_rows(frm);
        }
    });
}

// Recalculates all rows in the child table
function recalculate_all_rows(frm) {
    if (!frm.doc.severance_payment_table) return;

    frm.doc.severance_payment_table.forEach(row => {
        calculate_worked_year(frm, row);
        calculate_severance_earning(frm, row);
        calculate_income_tax(frm, row);
    });
    frm.refresh_field('severance_payment_table');
}

// Dynamic tax calculation function using cached slabs
function calculate_dynamic_tax(amount) {
    if (!amount || amount <= 0 || !cached_tax_slabs || cached_tax_slabs.length === 0) {
        return 0;
    }

    for (let slab of cached_tax_slabs) {
        let from_amt = flt(slab.from_amount);
        let to_amt = slab.to_amount ? flt(slab.to_amount) : Infinity;

        if (amount >= from_amt && amount <= to_amt) {
            let percent = flt(slab.percent_deduction);
            let deduction = flt(slab.return_amount);
            
            return (amount * (percent / 100)) - deduction;
        }
    }

    return 0;
}

function calculate_worked_year(frm, row) {
    if (row.joining_date && row.current_date) {
        const joining_date = frappe.datetime.str_to_obj(row.joining_date);
        const current_date = frappe.datetime.str_to_obj(row.current_date);

        const time_diff = current_date - joining_date;
        const working_days = Math.floor(time_diff / (1000 * 60 * 60 * 24)); 

        let years = current_date.getFullYear() - joining_date.getFullYear();
        let months = current_date.getMonth() - joining_date.getMonth();
        let days = current_date.getDate() - joining_date.getDate();

        if (days < 0) {
            months -= 1;
            const days_in_prev_month = new Date(current_date.getFullYear(), current_date.getMonth(), 0).getDate();
            days += days_in_prev_month;
        }
        if (months < 0) {
            years -= 1;
            months += 12;
        }

        const worked_years_decimal = years + (months / 12) + (days / 365);

        frappe.model.set_value(row.doctype, row.name, 'worked_year', `${years} years ${months} months and ${days} days`);
        frappe.model.set_value(row.doctype, row.name, 'working_days', working_days);
        frappe.model.set_value(row.doctype, row.name, 'worked_years_decimal', worked_years_decimal);

        calculate_severance_earning(frm, row);
        calculate_income_tax(frm, row);
    } else {
        frappe.model.set_value(row.doctype, row.name, 'worked_year', '');
        frappe.model.set_value(row.doctype, row.name, 'working_days', 0);
        frappe.model.set_value(row.doctype, row.name, 'worked_years_decimal', 0);
        frappe.model.set_value(row.doctype, row.name, 'income_tax_on_basic_salary', 0);
    }
}

function calculate_severance_earning(frm, row) {
    if (row.current_salary && row.worked_years_decimal) {
        const salary = flt(row.current_salary);
        const worked_years = flt(row.worked_years_decimal);

        let severance_earning = 0;

        if (worked_years >= 1) {
            severance_earning = salary;
            if (worked_years > 1) {
                const remaining_years = worked_years - 1;
                severance_earning += (remaining_years * (salary / 3));
            }
        }

        frappe.model.set_value(row.doctype, row.name, 'total_severance_earning', severance_earning);

        const total_paid_month = salary > 0 ? (severance_earning / salary) : 0;
        frappe.model.set_value(row.doctype, row.name, 'total_paid_month', total_paid_month);
    } else {
        frappe.model.set_value(row.doctype, row.name, 'total_severance_earning', 0);
        frappe.model.set_value(row.doctype, row.name, 'total_paid_month', 0);
    }
}

function calculate_income_tax(frm, row) {
    if (row.current_salary && row.total_paid_month) {
        let salary = flt(row.current_salary);
        let total_paid_month = flt(row.total_paid_month);
        let integer_month = Math.floor(total_paid_month);
        let fraction_month = total_paid_month - integer_month;
        
        let itax_on_basic_salary = calculate_dynamic_tax(salary) * integer_month;
        let prorated_salary = fraction_month * salary;
        let itax_on_prorate_salary = calculate_dynamic_tax(prorated_salary);

        let total_income_tax = itax_on_basic_salary + itax_on_prorate_salary;
        let total_severance_earning = flt(row.total_severance_earning) || 0;
        let net_severance_pay = total_severance_earning - total_income_tax;

        frappe.model.set_value(row.doctype, row.name, 'income_tax_on_basic_salary', itax_on_basic_salary);
        frappe.model.set_value(row.doctype, row.name, 'income_tax_on_prorate_salary', itax_on_prorate_salary);
        frappe.model.set_value(row.doctype, row.name, 'total_income_tax', total_income_tax);
        frappe.model.set_value(row.doctype, row.name, 'net_severance_pay', net_severance_pay);
    } else {
        frappe.model.set_value(row.doctype, row.name, 'income_tax_on_basic_salary', 0);
        frappe.model.set_value(row.doctype, row.name, 'income_tax_on_prorate_salary', 0);
