    }
});

// Helper to load tax slab standard records before running calculations
function fetch_tax_slabs_and_calculate(frm) {
    // If already loaded, run calculation immediately
    if (cached_tax_slabs) {
        calculate_annual_leave_for_child_table(frm);
        return;
    }

    // Fetch the latest or single Employee Income Tax Slab document
    frappe.db.get_list('Employee Income Tax Slab', {
        fields: ['name'],
        limit: 1
    }).then(records => {
        if (records && records.length > 0) {
            frappe.db.get_doc('Employee Income Tax Slab', records[0].name).then(doc => {
                // Cache the child table records
                cached_tax_slabs = doc.tax_slab_table || doc.employee_income_tax_slab_table || [];
                calculate_annual_leave_for_child_table(frm);
            });
        } else {
            frappe.msgprint(__('No Employee Income Tax Slab found. Tax calculations will default to 0.'));
            calculate_annual_leave_for_child_table(frm);
        }
    });
}

// Function to calculate leave payment per row in the child table
function calculate_annual_leave_for_row(frm, cdt, cdn) {  
    let row = locals[cdt][cdn];

    let work_day = row.work_day || 0;  
    let basic_salary = row.basic_salary || 0; 

    let payment_per_day = basic_salary / 26;     
    frappe.model.set_value(cdt, cdn, 'payment_per_day', payment_per_day);

    let gross_payment = work_day * payment_per_day;     
    frappe.model.set_value(cdt, cdn, 'gross_payment', gross_payment);

    let payment_per_month = gross_payment / 12;     
    frappe.model.set_value(cdt, cdn, 'payment_per_month', payment_per_month);

    let income_tax_basic = payment_per_month + basic_salary;     
    frappe.model.set_value(cdt, cdn, 'income_tax_basic', income_tax_basic);

    // Ensure we have tax slabs cached before running income tax calculations
    if (!cached_tax_slabs) {
        fetch_tax_slabs_and_calculate(frm);
    } else {
        calculate_income_tax_for_row(frm, cdt, cdn);
    }
}

// Dynamic tax calculator against cached slabs
function calculate_dynamic_tax(amount) {
    if (!amount || amount <= 0 || !cached_tax_slabs || cached_tax_slabs.length === 0) {
        return 0;
    }

    for (let slab of cached_tax_slabs) {
        let from_amt = flt(slab.from_amount);
        let to_amt = slab.to_amount ? flt(slab.to_amount) : Infinity;

        // Check if amount falls within current bracket
        if (amount >= from_amt && amount <= to_amt) {
            let percent = flt(slab.percent_deduction);
            let deduction = flt(slab.return_amount);
            
            return (amount * (percent / 100)) - deduction;
        }
    }

    return 0;
}

// Function to calculate income tax for each row
function calculate_income_tax_for_row(frm, cdt, cdn) {
    let row = locals[cdt][cdn];

    if (!row.basic_salary) {
        frappe.model.set_value(cdt, cdn, 'salary_income_tax', 0);
        frappe.model.set_value(cdt, cdn, 'income_tax_for_this_month', 0);
        frappe.model.set_value(cdt, cdn, 'income_tax_for_1_month', 0);
        frappe.model.set_value(cdt, cdn, 'income_tax_for_12_month', 0);
        frappe.model.set_value(cdt, cdn, 'total_deduction', row.other_deduction || 0);
        frappe.model.set_value(cdt, cdn, 'net_payment', row.gross_payment || 0);
        return;
    }

    let salary = row.basic_salary;
    let income_tax_basic = row.income_tax_basic || salary;

    let salary_income_tax = calculate_dynamic_tax(salary);
    let income_tax_for_this_month = calculate_dynamic_tax(income_tax_basic);

    frappe.model.set_value(cdt, cdn, 'salary_income_tax', salary_income_tax);
    frappe.model.set_value(cdt, cdn, 'income_tax_for_this_month', income_tax_for_this_month);

    let income_tax_for_1_month = income_tax_for_this_month - salary_income_tax;     
    frappe.model.set_value(cdt, cdn, 'income_tax_for_1_month', income_tax_for_1_month);

    let income_tax_for_12_month = income_tax_for_1_month * 12;     
    frappe.model.set_value(cdt, cdn, 'income_tax_for_12_month', income_tax_for_12_month);

    let total_deduction = (income_tax_for_12_month || 0) + (row.other_deduction || 0);     
    frappe.model.set_value(cdt, cdn, 'total_deduction', total_deduction);

    let net_payment = (row.gross_payment || 0) - total_deduction;     
    frappe.model.set_value(cdt, cdn, 'net_payment', net_payment);
}

// Function to calculate for all rows in the child table
function calculate_annual_leave_for_child_table(frm) {
    if (!frm.doc.annual_leave_payment_table) return;  

    frm.doc.annual_leave_payment_table.forEach(row => {
        let cdt = "Annual Leave Payment Table";  
        let cdn = row.name;

        calculate_annual_leave_for_row(frm, cdt, cdn);
    });
}

