function set_ethiopian_budget_year(frm) {
    let date = frm.doc.posting_date
        ? frappe.datetime.str_to_obj(frm.doc.posting_date)
        : new Date();

    let g_year = date.getFullYear();
    let month = date.getMonth() + 1;
    let day = date.getDate();

    let et_year;

    // Budget year starts on July 08
    if (month > 7 || (month === 7 && day >= 8)) {
        et_year = g_year - 7;
    } else {
        et_year = g_year - 8;
    }

    frm.set_value('budget_year', et_year.toString());
}




