// ============================================================
// Set Item Conversion Factor
// ============================================================

function set_item_conversion_factor(
    frm,
    cdt,
    cdn
) {

    let row = locals[cdt][cdn];

    if (!row.item_code) {
        return;
    }

    frappe.call({

        method: "frappe.client.get",

        args: {

            doctype: "Item",

            name: row.item_code

        },

        callback: function(r) {

            if (!r.message) {
                return;
            }

            let item = r.message;

            let conversion_factor = 1;


            // ------------------------------------------------
            // Stock UOM
            // ------------------------------------------------

            if (
                item.stock_uom &&
                row.uom === item.stock_uom
            ) {

                conversion_factor = 1;

            }


            // ------------------------------------------------
            // Item UOM Conversion
            // ------------------------------------------------

            else if (
                item.uoms &&
                item.uoms.length
            ) {

                let uom_row =
                    item.uoms.find(function(uom) {

                        return uom.uom === row.uom;

                    });


                if (uom_row) {

                    conversion_factor =
                        flt(
                            uom_row.conversion_factor
                        ) || 1;

                }

            }


            // ------------------------------------------------
            // Set Conversion Factor
            // ------------------------------------------------

            frappe.model.set_value(
                cdt,
                cdn,
                "conversion_factor",
                conversion_factor
            );


            // ------------------------------------------------
            // Calculate Stock Qty
            // ------------------------------------------------

            let stock_qty =
                flt(row.qty || 0) *
                flt(conversion_factor || 1);


            frappe.model.set_value(
                cdt,
                cdn,
                "stock_qty",
                stock_qty
            );

        }

    });

}


// ============================================================
// Update Stock Qty when Qty changes
// ============================================================

function update_stock_qty(
    frm,
    cdt,
    cdn
) {

    let row = locals[cdt][cdn];

    let qty =
        flt(row.qty || 0);

    let conversion_factor =
        flt(row.conversion_factor || 1);

    let stock_qty =
        qty * conversion_factor;


    frappe.model.set_value(
        cdt,
        cdn,
        "stock_qty",
        stock_qty
    );

}


// ============================================================
// Validate Duplicate Items
// ============================================================

function validate_duplicate_items(frm) {

    let item_rows = {};

    for (let row of frm.doc.items || []) {

        if (!row.item_code) {
            continue;
        }


        if (item_rows[row.item_code]) {

            frappe.throw(
                __(
                    "Duplicate Item: {0} appears more than once in the Material Return Request. Each item can only appear once.",
                    [row.item_code]
                )
            );

        }


        item_rows[row.item_code] = row.name;

    }

}


// ============================================================
// Item Filter Based on Return Type
// ============================================================

function set_return_item_filter(frm) {

    if (!frm.fields_dict.items) {
        return;
    }


    let item_field =
        frm.fields_dict.items.grid.get_field(
            "item_code"
        );


    if (!item_field) {
        return;
    }


    item_field.get_query = function(
        doc,
        cdt,
        cdn
    ) {

        let filters = {};


        // ------------------------------------------------
        // Inventory
        // ------------------------------------------------

        if (
            doc.return_type === "Inventory"
        ) {

            filters = {

                is_stock_item: 1,

                is_fixed_asset: 0

            };

        }


        // ------------------------------------------------
        // Fixed Asset
        // ------------------------------------------------

        else if (
            doc.return_type === "Fixed Asset"
        ) {

            filters = {

                is_fixed_asset: 1

            };

        }


        return {

            filters: filters

        };

    };

}


// ============================================================
// Validate Item Type
// ============================================================

async function validate_return_items(frm) {

    if (!frm.doc.return_type) {

        frappe.throw(
            __("Please select Return Type.")
        );

    }


    for (
        let row of frm.doc.items || []
    ) {

        if (!row.item_code) {
            continue;
        }


        let r =
            await frappe.db.get_value(
                "Item",
                row.item_code,
                [
                    "is_stock_item",
                    "is_fixed_asset"
                ]
            );


        let item = r.message;


        if (!item) {

            frappe.throw(
                __(
                    "Row {0}: Item {1} could not be found.",
                    [
                        row.idx,
                        row.item_code
                    ]
                )
            );

        }


        // ------------------------------------------------
        // Fixed Asset
        // ------------------------------------------------

        if (
            frm.doc.return_type ===
            "Fixed Asset"
        ) {

            if (!item.is_fixed_asset) {

                frappe.throw(
                    __(
                        "Row {0}: {1} is not a Fixed Asset. Only Fixed Assets are allowed.",
                        [
                            row.idx,
                            row.item_code
                        ]
                    )
                );

            }

        }


        // ------------------------------------------------
        // Inventory
        // ------------------------------------------------

        if (
            frm.doc.return_type ===
            "Inventory"
        ) {

            if (
                !item.is_stock_item ||
                item.is_fixed_asset
            ) {

                frappe.throw(
                    __(
                        "Row {0}: {1} is not an Inventory Item. Only Stock Items are allowed.",
                        [
                            row.idx,
                            row.item_code
                        ]
                    )
                );

            }

        }

    }

}


