function create_stock_entry_from_material_return(frm) {

    frappe.call({

        method:
            "standard.override.material_return_request.get_items",

        args: {
            source_name: frm.doc.name
        },

        freeze: true,

        freeze_message:
            __("Creating Stock Entry..."),

        callback(r) {

            if (!r.message) {

                frappe.msgprint(
                    __("No item data was returned from this Material Return Request.")
                );

                return;
            }

            let data = r.message;

            // ------------------------------------------------
            // Check remaining items
            // ------------------------------------------------

            if (!data.items || !data.items.length) {

                frappe.msgprint(
                    __("There are no remaining quantities to return.")
                );

                return;
            }

            // ------------------------------------------------
            // Create new Stock Entry
            // ------------------------------------------------

            frappe.model.with_doctype(
                "Stock Entry",
                function () {

                    let stock_entry =
                        frappe.model.get_new_doc(
                            "Stock Entry"
                        );

                    // ------------------------------------------------
                    // Parent fields
                    // ------------------------------------------------

                    stock_entry.stock_entry_type =
                        data.stock_entry_type;

                    stock_entry.project =
                        data.project;

                    stock_entry.custom_reference_document =
                        data.custom_reference_document;

                    stock_entry.custom_reference_no =
                        data.custom_reference_no;

                    stock_entry.to_warehouse =
                        data.to_warehouse;


                    // ------------------------------------------------
                    // Items
                    // ------------------------------------------------

                    (data.items || []).forEach(function (data_item) {

                        let item =
                            frappe.model.add_child(
                                stock_entry,
                                "Stock Entry Detail",
                                "items"
                            );

                        item.item_code =
                            data_item.item_code;

                        item.item_name =
                            data_item.item_name;

                        item.qty =
                            data_item.qty;

                        item.uom =
                            data_item.uom;

                        item.conversion_factor =
                            data_item.conversion_factor;

                        item.s_warehouse =
                            data_item.warehouse;

                    });


                    // ------------------------------------------------
                    // Open Stock Entry
                    // ------------------------------------------------

                    frappe.set_route(
                        "Form",
                        "Stock Entry",
                        stock_entry.name
                    );

                }
            );

        }
    });
}

