function get_items_from_material_return(frm) {

    let multi_select_dialog = new frappe.ui.form.MultiSelectDialog({

        doctype: "Material Return Request",
        target: frm,

        setters: {
            return_type: frm.doc.return_type || ""
        },

        add_filters_group: 1,

        get_query() {
            return {
                filters: {
                    docstatus: 1,
                    per_returned: ["<", 100]
                }
            };
        },

        action(selections) {

            if (!selections.length) {
                frappe.msgprint(
                    __("Please select a Material Return Request")
                );
                return;
            }

            frappe.call({

                method:
                    "standard.override.material_return_request.get_items",

                args: {
                    source_name: selections[0]
                },

                callback(r) {

                    if (!r.message) {
                        return;
                    }

                    let data = r.message;

                    // --------------------------------------------------
                    // Parent fields
                    // --------------------------------------------------

                    frm.set_value(
                        "stock_entry_type",
                        data.stock_entry_type
                    );

                    frm.set_value(
                        "project",
                        data.project
                    );

                    frm.set_value(
                        "custom_reference_document",
                        data.custom_reference_document
                    );

                    frm.set_value(
                        "custom_reference_no",
                        data.custom_reference_no
                    );

                    frm.set_value(
                        "to_warehouse",
                        data.to_warehouse
                    );

                    // --------------------------------------------------
                    // Items
                    // --------------------------------------------------

                    frm.clear_table("items");

                    (data.items || []).forEach(function(item) {

                        let child = frm.add_child("items");

                        child.item_code = item.item_code;
                        child.item_name = item.item_name;
                        child.qty = item.qty;
                        child.uom = item.uom;
                        child.conversion_factor =
                            item.conversion_factor;
                        child.s_warehouse = item.warehouse;

                    });

                    frm.refresh_field("items");

                    // --------------------------------------------------
                    // Close dialog
                    // --------------------------------------------------

                    multi_select_dialog.dialog.hide();
                }
            });
        }
    });
}


