function create_stock_entry_from_fuel_request(frm) {

    frappe.call({

        method: "standard.override.fuel_request.get_items",

        args: {
            source_name: frm.doc.name
        },

        freeze: true,
        freeze_message: __("Creating Stock Entry..."),

        callback(r) {

            if (!r.message) {
                frappe.msgprint(
                    __("No item data was returned from this Fuel Request Form.")
                );
                return;
            }

            let data = r.message;

            // Create new Stock Entry
            frappe.model.with_doctype("Stock Entry", function () {

                let stock_entry = frappe.model.get_new_doc("Stock Entry");

                // ------------------------------------------------
                // Parent fields
                // ------------------------------------------------

                stock_entry.stock_entry_type = data.stock_entry_type;
                stock_entry.project = data.project;
                stock_entry.custom_reference_document =
                    data.custom_reference_document;
                stock_entry.custom_reference_no =
                    data.custom_reference_no;

                stock_entry.from_warehouse = data.warehouse;

                // ------------------------------------------------
                // Item
                // ------------------------------------------------

                let item = frappe.model.add_child(
                    stock_entry,
                    "Stock Entry Detail",
                    "items"
                );

                item.item_code = data.item.item_code;
                item.item_name = data.item.item_name;
                item.qty = data.item.qty;
                item.uom = data.item.uom;
                item.conversion_factor = data.item.conversion_factor;

                item.s_warehouse = data.item.warehouse;

                // ------------------------------------------------
                // Open Stock Entry
                // ------------------------------------------------

                frappe.set_route(
                    "Form",
                    "Stock Entry",
                    stock_entry.name
                );

            });

        }

    });

}

