// ==========================================================

function set_items_grid_read_only(frm) {

    const grid = frm.fields_dict.items?.grid;

    if (!grid) {
        return;
    }

    // Prevent adding rows
    grid.cannot_add_rows = true;

    // Prevent deleting rows
    grid.cannot_delete_rows = true;

    // Prevent duplicating rows
    grid.cannot_duplicate = true;

    // Hide Add Row button
    $(grid.wrapper)
        .find(".grid-add-row")
        .hide();

    // Hide Delete/Remove controls
    $(grid.wrapper)
        .find(".grid-remove-rows")
        .hide();

    // Hide Duplicate button
    $(grid.wrapper)
        .find(".grid-duplicate-row")
        .hide();

    // Hide Move buttons
    $(grid.wrapper)
        .find(".grid-move-row")
        .hide();
}


