// STATUS
// ==========================================================

function update_status_based_on_child(frm) {

    let new_status = null;

    const items = frm.doc.items || [];

    // If there is a rejected item, parent is Rejected
    const has_rejected = items.some(function(row) {
        return row.status === "Rejected";
    });

    if (has_rejected) {

        new_status = "Rejected";

    } else if (items.length > 0) {

        new_status = "Accepted";
    }

    // IMPORTANT:
    // Do nothing if the status is already correct.
    if (!new_status || frm.doc.status === new_status) {
        return;
    }

    frm.set_value("status", new_status);
}


