function validate_duplicate_accepted_inspection(frm) {

    if (!frm.doc.purchase_order) {
        return;
    }

    // Do not check against itself when editing
    let filters = {
        purchase_order: frm.doc.purchase_order,
        status: "Accepted",
        docstatus: ["!=", 2]
    };

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Purchase Inspection",
            filters: filters,
            fields: ["name", "status"],
            limit_page_length: 1
        },
        async: false,
        callback: function(r) {

            if (!r.message || !r.message.length) {
                return;
            }

            // Ignore the current document
            let existing_inspection = r.message.find(function(row) {
                return row.name !== frm.doc.name;
            });

            if (existing_inspection) {

                frappe.msgprint({
                    title: __("Duplicate Purchase Inspection"),
                    message: __(
                        "Purchase Order <b>{0}</b> has already been accepted in Purchase Inspection <b>{1}</b>.<br><br>" +
                        "A new Purchase Inspection cannot be created for an already accepted Purchase Order.",
                        [
                            frm.doc.purchase_order,
                            existing_inspection.name
                        ]
                    ),
                    indicator: "red"
                });

                frappe.validated = false;
            }
        }
    });
}

function validate_inspection_date(frm) {

    if (!frm.doc.inspection_date_gc) {
        return;
    }

    // Get dates as YYYY-MM-DD strings
    const inspection_date = frm.doc.inspection_date_gc;
    const today = frappe.datetime.get_today();

    // Compare date only — no time
    if (inspection_date > today) {

        frappe.msgprint({
            title: __("Invalid Inspection Date"),
            message: __(
                "Inspection Date cannot be a future date.<br><br>" +
                "Please enter today or an earlier date."
            ),
            indicator: "red"
        });

        frappe.validated = false;
    }
}

