// =============================================================
// FETCH HANDOVER STOCK
// =============================================================

function fetch_handover_stock(frm) {

    frappe.call({

        method: "get_handover_stock_balance",

        args: {
            warehouse: frm.doc.warehouse,
            handover_date_gc: frm.doc.handover_date_gc
        },

        freeze: true,

        freeze_message: __('Fetching stock balance as of handover date...'),

        callback: function (response) {

            // =================================================
            // CHECK RESPONSE
            // =================================================

            if (!response.message) {

                frappe.msgprint(
                    __('No stock balance was returned.')
                );

                return;
            }


            if (response.message.length === 0) {

                frappe.msgprint(
                    __(
                        'No stock was available in the selected warehouse on the handover date.'
                    )
                );

                return;
            }


            // =================================================
            // CLEAR EXISTING ITEMS
            // =================================================

            frm.clear_table("items");


            // =================================================
            // ADD STOCK ITEMS
            // =================================================

            response.message.forEach(function (row) {

                let child = frm.add_child("items");


                // Item
                child.item_code = row.item_code;


                // Item Name
                child.item_name = row.item_name || "";


                // Description
                child.description = row.description || "";


                // UOM
                child.uom = row.uom || "";


                // Historical Stock Balance
                child.stock_level = flt(row.stock_level);


                // Valuation Rate
                if (frappe.meta.has_field(
                    "Warehouse Handover Item",
                    "unit_price"
                )) {
                    child.unit_price = flt(row.unit_price);
                }


                // Total Amount
                if (frappe.meta.has_field(
                    "Warehouse Handover Item",
                    "total_amount"
                )) {
                    child.total_amount =
                        flt(row.total_amount);
                }

            });


            // =================================================
            // REFRESH TABLE
            // =================================================

            frm.refresh_field("items");


            // =================================================
            // SUCCESS MESSAGE
            // =================================================

            frappe.show_alert({
                message: __(
                    '{0} stock items fetched for {1} as of {2}',
                    [
                        response.message.length,
                        frm.doc.warehouse,
                        frm.doc.handover_date_gc
                    ]
                ),

                indicator: "green"
            });

        }

    });

}

