frappe.ui.form.on('Recruitment Application New Employee', {

    // 4. ማስታወቂያው የወጣበት ቁጥር
    recruitment_notice: async function(frm) {

        // Clear previous designation options/value
        frm.set_df_property(
            'designation_choice',
            'options',
            []
        );

        frm.set_value(
            'designation_choice',
            null
        );

        // Clear previous employment type
        frm.set_value(
            'employement_type',
            null
        );

        // Clear previously loaded rows
        frm.recruitment_designation_rows = [];

        // Nothing selected
        if (!frm.doc.recruitment_notice) {
            return;
        }

        try {

            // Get the selected Recruitment Notice
            const notice = await frappe.db.get_doc(
                'Recruitment Notice',
                frm.doc.recruitment_notice
            );

            // -----------------------------------------
            // Get designation rows from child table
            // -----------------------------------------
            const tableRows = notice.table_5 || [];

            // Save child table rows for later use
            frm.recruitment_designation_rows = tableRows;


            // -----------------------------------------
            // Get unique designations
            // -----------------------------------------
            const designations = [
                ...new Set(
                    tableRows
                        .map(row => row.designation)
                        .filter(d => d)
                )
            ];


            // -----------------------------------------
            // No designation found
            // -----------------------------------------
            if (designations.length === 0) {

                frappe.msgprint(
                    'No designations found in this Recruitment Notice.'
                );

                return;
            }


            // -----------------------------------------
            // Populate Select field
            // -----------------------------------------
            frm.set_df_property(
                'designation_choice',
                'options',
                designations.join('\n')
            );

            frm.refresh_field(
                'designation_choice'
            );


            // -----------------------------------------
            // If only one designation exists,
            // select it automatically.
            // -----------------------------------------
            if (designations.length === 1) {

                frm.set_value(
                    'designation_choice',
                    designations[0]
                );
            }


            frappe.show_alert(
                `Loaded ${designations.length} designation(s) from the Recruitment Notice.`
            );

        } catch (error) {

            console.error(
                'Error loading Recruitment Notice:',
                error
            );

            frappe.msgprint(
                'Unable to load the selected Recruitment Notice.'
            );
        }
    },


    // -----------------------------------------
    // When designation is selected
    // -----------------------------------------
    designation_choice: function(frm) {

        if (
            !frm.doc.designation_choice ||
            !frm.recruitment_designation_rows
        ) {
            return;
        }


        // Find the selected designation
        const matchedRow =
            frm.recruitment_designation_rows.find(
                row =>
                    row.designation ===
                    frm.doc.designation_choice
            );


        // -----------------------------------------
        // Automatically set employment type
        // -----------------------------------------
        if (
            matchedRow &&
            matchedRow.recruitment_type
        ) {

            frm.set_value(
                'employement_type',
                matchedRow.recruitment_type
            );

        } else {

            frm.set_value(
                'employement_type',
                null
            );
        }
    },


    // -----------------------------------------
    // Optional:
    // Clear designation when creating a new form
    // -----------------------------------------
    onload: function(frm) {

        if (frm.is_new()) {

            frm.recruitment_designation_rows = [];

            frm.set_df_property(
                'designation_choice',
                'options',
                []
            );
        }
    }

});

