function check_discipline_case(frm) {
    // Only run for new/draft docs still in the Registered state
    if (frm.doc.docstatus !== 0 || frm.doc.workflow_state !== 'Registered') {
        return;
    }

    if (!frm.doc.employee_id || !frm.doc.application_date_gc) {
        return;
    }

    frappe.model.with_doc('Employee', frm.doc.employee_id, function() {
        let employee = frappe.model.get_doc('Employee', frm.doc.employee_id);
        let discipline_rows = employee.custom_displine || [];
        let app_date = frappe.datetime.str_to_obj(frm.doc.application_date_gc);

        let matched_cases = [];

        discipline_rows.forEach(function(row) {
            if (row.start_date && row.end_date) {
                let start = frappe.datetime.str_to_obj(row.start_date);
                let end = frappe.datetime.str_to_obj(row.end_date);

                if (app_date >= start && app_date <= end) {
                    matched_cases.push(row);
                }
            }
        });

        if (matched_cases.length > 0) {
            show_discipline_warning(frm, matched_cases);
        }
    });
}

function show_discipline_warning(frm, cases) {
    let rows_html = cases.map(function(row) {
        return `
            <tr>
                <td>${row.data4 || '-'}</td>
                <td>${row.data1 || '-'}</td>
                <td>${frappe.datetime.str_to_user(row.start_date) || '-'}</td>
                <td>${frappe.datetime.str_to_user(row.end_date) || '-'}</td>
                <td>${row.data6 || '-'}</td>
            </tr>
        `;
    }).join('');

    let message = `
        <div style="text-align:center; margin-bottom: 15px;">
            <span style="font-size: 42px;">⚠️</span>
            <h3 style="color:#d33; margin: 10px 0 5px 0;">Active Discipline Case Found</h3>
            <p style="color:#666; margin:0;">This employee has a disciplinary record active on the application date.</p>
        </div>
        <table class="table table-bordered" style="margin-top:10px;">
            <thead>
                <tr style="background:#fff3f3;">
                    <th>Violation Type</th>
                    <th>Disciplinary Action</th>
                    <th>Start Date</th>
                    <th>End Date</th>
                    <th>Decided By</th>
                </tr>
            </thead>
            <tbody>
                ${rows_html}
            </tbody>
        </table>
        <p style="margin-top:15px; color:#888; font-size:12px;">
            Please review this case before proceeding with the recruitment process.
        </p>
    `;

    frappe.msgprint({
        title: '🚨 Discipline Alert',
        message: message,
        indicator: 'red'
    });
}

