function compare_and_rank_providers(frm) {
    if (!frm.doc.lobed_operators || frm.doc.lobed_operators.length === 0) {
        frappe.msgprint(__('No applicants to compare. Please fetch applications first.'));
        return;
    }

    let sorted_rows = [...frm.doc.lobed_operators].sort((a, b) => flt(b.total_100) - flt(a.total_100));

    frm.clear_table('lobed_operators_rank');

    sorted_rows.forEach((src, idx) => {
        let row = frm.add_child('lobed_operators_rank', {
            names: src.names,
            from_3: src.from_3,
            from_23: src.from_23,
            perf: src.perf,
            displine: src.displine,
            age_nu: src.age_nu,
            disciplin: src.discipline_10,
            gen: src.gen,
            gend_3: src.gend_3,
            from_bos: src.from_bos,
            total_100: src.total_100,
            rank: idx + 1
        });
    });

    frm.refresh_field('lobed_operators_rank');
    frappe.show_alert({ message: __('Ranking complete'), indicator: 'green' }, 3);
}
