    age_nu: function (frm, cdt, cdn) { recalculate_total(frm, cdt, cdn); },
    perf: function (frm, cdt, cdn) { recalculate_total(frm, cdt, cdn); },
    gend_3: function (frm, cdt, cdn) { recalculate_total(frm, cdt, cdn); }
