function recalculate_total(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    let total =  flt(row.app.displine,) +
                        flt(row.from_23) +
                        flt(row.from_3) +
                        flt(row.age_nu) +
                        flt(row.perf) +
                        flt(row.gend_3);
    frappe.model.set_value(cdt, cdn, 'total_100', total);
}
function fetch_applications(frm) {
    if (!frm.doc.from_date || !frm.doc.to_date || !frm.doc.tyep_of_training || !frm.doc.edu_level) {
        frappe.msgprint(__('Please enter both From Date and To Date, Type Of Training, and Education Level'));
        return;
    }

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Education Application",
            filters: [
                ["application_date_gc", ">=", frm.doc.from_date],
                ["application_date_gc", "<=", frm.doc.to_date],
                ["tyep_of_training", "=", frm.doc.tyep_of_training],
                ["edu_level", "=", frm.doc.edu_level],
                ["workflow_state", "=", "Accepted"]
            ],
            fields: [
                "name",
                "employee_id",
                "employee_name",
                "gender",
                "employement_type",
                "application_date_gc",
                "discipline",
                "bsc11",
                "edu_level",
                "result",
                "ቀረቤታ_ከ35",
                "ker_30"
            ],
            limit_page_length: 0
        },
        callback: function (r) {
            if (!r.message || r.message.length === 0) {
                frappe.msgprint(__('No accepted applications found for the selected criteria.'));
                return;
            }

            frm.clear_table('lobed_operators');

            r.message.forEach(app => {
                let row = frm.add_child("lobed_operators", {
                    employee: app.employee_id,
                    names: app.employee_name,
                    employement_type: app.employement_type,
                    gen: app.gender,
                    from_3: app.ቀረቤታ_ከ35,
                    from_23: app.ker_30,
                    perf: app.bsc11,
                    displine: app.discipline
                });

                row.gend_3 = (app.gender === 'ሴት') ? 5 : 0;

                row.total_100 =
                    flt(row.displine) +
                    flt(row.from_23) +
                    flt(row.from_3) +
                    flt(row.age_nu) +
                    flt(row.perf) +
                    flt(row.gend_3);
            });

            frm.refresh_field('lobed_operators');
            frappe.show_alert({ message: __('{0} applications fetched', [r.message.length]), indicator: 'green' }, 3);
        }
    });
}
