function fetch_employees_for_project(frm) {
    if (!frm.doc.projects) return;

    frappe.db.get_list('Employee', {
        filters: {
            custom_project: frm.doc.projects,
            status: 'Active'
        },
        fields: ['name', 'employee_name', 'designation'],
        limit: 0
    }).then(employees => {
        if (!employees.length) {
            frappe.msgprint(__('No active employees found for the selected Project.'));
            frm.clear_table('uniform_registration_type');
            frm.refresh_field('uniform_registration_type');
            return;
        }

        frm.clear_table('uniform_registration_type');

        let skipped = [];

        // Build a promise chain so rows are added only for employees with uniform data
        let chain = Promise.resolve();

        employees.forEach(emp => {
            chain = chain.then(() => {
                if (!emp.designation) {
                    skipped.push(emp.employee_name || emp.name);
                    return;
                }

                return frappe.db.get_doc('Designation', emp.designation).then(designation_doc => {
                    let uniform_rows = designation_doc.custom_uniform_registration || [];

                    if (!uniform_rows.length) {
                        // No uniform setup for this designation — skip this employee
                        skipped.push(emp.employee_name || emp.name);
                        return;
                    }

                    let child = frm.add_child('uniform_registration_type');
                    frappe.model.set_value(child.doctype, child.name, 'employee_id', emp.name);
                    frappe.model.set_value(child.doctype, child.name, 'employee_name', emp.employee_name);
                    frappe.model.set_value(child.doctype, child.name, 'designation', emp.designation);

                    let source = uniform_rows[0];
                    let fields = [
                        'data_6','data_7','data_8','data_9',
                        'data_10','data_11','data_12','data_13',
                        'data_15','data_16','data_17','data_18',
                        'data_20','data_21','data_22','data_23',
                        'data_25','data_26','data_27','data_28',
                        'data_30','data_31','data_32','data_33',
                        'data_35','data_36','data_37','data_38',
                        'data_40','data_41','data_42','data_43',
                        'data_45','data_46','data_47','data_48',
                        'data_50','data_51','data_52','data_53',
                        'data_54','data_55','data_56','da_77',
                        'data_57','data_58','data_59','da_78',
                        'data_60','data_61','data_62','da_80',
                        'total_amount'
                    ];

                    fields.forEach(f => {
                        frappe.model.set_value(child.doctype, child.name, f, source[f]);
                    });
                });
            });
        });

        chain.then(() => {
            frm.refresh_field('uniform_registration_type');

            if (skipped.length) {
                frappe.msgprint(__('Skipped {0} employee(s) with no Uniform Registration set on their Designation: {1}', [skipped.length, skipped.join(', ')]));
            }
        });

    }).catch(err => {
        frappe.msgprint(__('Could not fetch employees for the selected Project.'));
        console.error(err);
    });
}
function populate_uniform_fields(cdt, cdn, designation) {
    frappe.db.get_doc('Designation', designation)
