frappe.ui.form.on("Item", {

    // =========================================================
    // ONLOAD
    // =========================================================

    onload: function (frm) {

        // Only allow Item Groups that are actual selectable groups
        frm.set_query("item_group", function () {
            return {
                filters: {
                    "is_group": 0
                }
            };
        });

        // -----------------------------------------------------
        // DUPLICATED ITEM
        // -----------------------------------------------------
        //
        // A duplicated Item is a new document but already has
        // the old Item Code.
        //
        // Generate a new Item Code.
        //

        if (
            frm.is_new() &&
            frm.doc.__islocal &&
            frm.doc.item_group &&
            frm.doc.item_code
        ) {
            generate_item_code_from_existing(frm);
        }
    },


    // =========================================================
    // ITEM GROUP CHANGE
    // =========================================================

    item_group: function (frm) {

        if (!frm.doc.item_group) {
            return;
        }

        generate_item_code_from_existing(frm);
    },


    // =========================================================
    // VALIDATE
    // =========================================================

    validate: function (frm) {

        // -----------------------------------------------------
        // Item Name required
        // -----------------------------------------------------

        if (!frm.doc.item_name) {

            frappe.throw(
                __("Please enter Item Name")
            );
        }


        // -----------------------------------------------------
        // Description
        // -----------------------------------------------------

        if (
            !frm.doc.description ||
            frm.doc.description === frm.doc.item_code
        ) {

            frm.set_value(
                "description",
                frm.doc.item_name
            );
        }


        // -----------------------------------------------------
        // Generate Item Code if missing
        // -----------------------------------------------------

        if (
            !frm.doc.item_code &&
            frm.doc.item_group
        ) {

            frappe.validated = false;

            generate_item_code_from_existing(
                frm,
                true,
                function () {

                    if (
                        !frm.doc.description ||
                        frm.doc.description === frm.doc.item_code
                    ) {

                        frm.set_value(
                            "description",
                            frm.doc.item_name
                        );
                    }

                    frappe.validated = true;

                    frm.save();
                }
            );
        }
    },


    // =========================================================
    // BEFORE SAVE
    // =========================================================

    before_save: async function (frm) {

        // Don't check if there is no Item Name
        if (!frm.doc.item_name) {
            return;
        }

        // Don't check an existing Item unless its name changed
        if (
            !frm.is_new() &&
            !frm.doc.__islocal &&
            !frm.doc.__unsaved
        ) {
            return;
        }

        const duplicates =
            await find_possible_duplicate_items(frm);

        if (!duplicates || !duplicates.length) {
            return;
        }

        // -----------------------------------------------------
        // Prevent immediate save
        // -----------------------------------------------------

        frappe.validated = false;

        await show_duplicate_warning(
            frm,
            duplicates
        );
    }
});


// =========================================================
// GENERATE ITEM CODE
// =========================================================

function generate_item_code_from_existing(
    frm,
    is_sync = false,
    callback
) {

    frappe.call({

        method: "frappe.client.get_list",

        args: {

            doctype: "Item",

            fields: [
                "item_code"
            ],

            filters: {
                item_group: frm.doc.item_group
            },

            order_by: "item_code desc",

            limit_page_length: 1
        },

        async: !is_sync,

        callback: function (res) {

            if (
                res.message &&
                res.message.length > 0
            ) {

                // ---------------------------------------------
                // Existing Items
                // ---------------------------------------------

                let last_code =
                    res.message[0].item_code;

                let parts =
                    last_code.split("-");

                if (parts.length === 3) {

                    let main = parts[0];

                    let sub = parts[1];

                    let last_number =
                        parseInt(parts[2]) || 0;

                    let next_number =
                        last_number + 1;

                    let next_code =
                        `${main}-${sub}-${String(next_number).padStart(4, "0")}`;

                    frm.set_value(
                        "item_code",
                        next_code
                    );

                    frm.set_df_property(
                        "item_code",
                        "read_only",
                        1
                    );

                    frm.refresh_field(
                        "item_code"
                    );
                }

                if (callback) {
                    callback();
                }

            } else {

                // ---------------------------------------------
                // No existing Items
                // ---------------------------------------------

                frappe.call({

                    method:
                        "frappe.client.get_value",

                    args: {

                        doctype:
                            "Item Group",

                        filters: {
                            name:
                                frm.doc.item_group
                        },

                        fieldname: [
                            "custom_main_code",
                            "custom_sub_code"
                        ]
                    },

                    callback: function (r) {

                        if (r.message) {

                            let main =
                                String(
                                    r.message.custom_main_code || "0"
                                ).padStart(2, "0");

                            let sub =
                                String(
                                    r.message.custom_sub_code || "0"
                                ).padStart(3, "0");

                            let next_code =
                                `${main}-${sub}-0001`;

                            frm.set_value(
                                "item_code",
                                next_code
                            );

                            frm.set_df_property(
                                "item_code",
                                "read_only",
                                1
                            );

                            frm.refresh_field(
                                "item_code"
                            );
                        }

                        if (callback) {
                            callback();
                        }
                    }
                });
            }
        }
    });
}


// =========================================================
// FIND POSSIBLE DUPLICATES
// =========================================================

async function find_possible_duplicate_items(frm) {

    try {

        const response =
            await frappe.call({

                method:
                    "find_possible_duplicate_items",

                args: {

                    item_name:
                        frm.doc.item_name,

                    item_group:
                        frm.doc.item_group,

                    item_code:
                        frm.doc.item_code
                }
            });

        return response.message || [];

    } catch (error) {

        console.error(
            "Item duplicate check failed:",
            error
        );

        // Don't prevent saving if duplicate checker itself fails
        return [];
    }
}


// =========================================================
// DUPLICATE WARNING
// =========================================================

function show_duplicate_warning(
    frm,
    duplicates
) {

    return new Promise(function (resolve) {

        let html = `
            <div style="
                margin-bottom: 15px;
                padding: 10px;
                background: #fff3cd;
                border: 1px solid #ffe69c;
                border-radius: 5px;
            ">

                <strong>
                    ⚠ Possible Duplicate Item
                </strong>

                <br>

                The Item Name you entered is similar
                to existing Item(s).

                <br>

                Please check before creating
                another Item.
            </div>

            <table class="table table-bordered">

                <thead>

                    <tr>

                        <th>
                            Item Name
                        </th>

                        <th>
                            Item Code
                        </th>

                        <th>
                            UOM
                        </th>

                        <th>
                            Similarity
                        </th>

                    </tr>

                </thead>

                <tbody>
        `;

        duplicates.forEach(function (item) {

            html += `
                <tr>

                    <td>
                        <strong>
                            ${frappe.utils.escape_html(
                                item.item_name || ""
                            )}
                        </strong>
                    </td>

                    <td>
                        ${frappe.utils.escape_html(
                            item.item_code || ""
                        )}
                    </td>

                    <td>
                        ${frappe.utils.escape_html(
                            item.uom || ""
                        )}
                    </td>

                    <td>
                        ${item.score}%
                    </td>

                </tr>
            `;
        });

        html += `
                </tbody>

            </table>

            <div style="
                margin-top: 10px;
                color: #666;
            ">

                <strong>
                    Current Item:
                </strong>

                ${frappe.utils.escape_html(
                    frm.doc.item_name || ""
                )}

            </div>
        `;

        let dialog =
            new frappe.ui.Dialog({

                title:
                    __("Possible Duplicate Items"),

                size:
                    "large",

                fields: [
                    {
                        fieldname:
                            "duplicate_html",

                        fieldtype:
                            "HTML"
                    }
                ],

                primary_action_label:
                    __("Continue Anyway"),

                primary_action: function () {

                    dialog.hide();

                    // -------------------------------------------------
                    // Mark that the user intentionally accepted
                    // the possible duplicate.
                    // -------------------------------------------------

                    frm.__duplicate_warning_accepted = true;

                    resolve(true);

                    // -------------------------------------------------
                    // Save again
                    // -------------------------------------------------

                    setTimeout(function () {

                        frm.save();

                    }, 100);
                },

                secondary_action_label:
                    __("Cancel"),

                secondary_action: function () {

                    dialog.hide();

                    resolve(false);
                }
            });

        dialog.fields_dict.duplicate_html.$wrapper.html(
            html
        );

        dialog.show();
    });
}

