function calculate_row_total(frm, cdt, cdn) {
    let row = locals[cdt][cdn];  // Get the current row
    let male = row.male || 0;     // Ensure male is a number
    let female = row.female || 0; // Ensure female is a number

    frappe.model.set_value(cdt, cdn, 'total', male + female); // Update total for the row
}

function calculate_all_totals(frm) {
    (frm.doc.training_request_format_table || []).forEach(row => {
        frappe.model.set_value(row.doctype, row.name, 'total', (row.male || 0) + (row.female || 0));
    });
}



