function fetch_designations(frm) {
    // Clear existing child table rows
    frm.clear_table('table_4');
    frm.refresh_field('table_4');

    if (!frm.doc.from) return;

    // Fetch all Company Structure docs linked to this department
    frappe.db.get_list('Company Structure', {
        fields: ['designation', 'department'],
        filters: {
            department: frm.doc.from
        },
        limit: 500
    }).then(function(records) {
        if (!records || records.length === 0) {
            frappe.msgprint(__('No designations found for this department.'));
            return;
        }

        records.forEach(function(record) {
            if (record.designation) {
                let row = frm.add_child('table_4');
                row.designation = record.designation;
            }
        });

        frm.refresh_field('table_4');
        frappe.show_alert({
            message: __('Fetched {0} designation(s)', [records.length]),
            indicator: 'green'
        });
    });
}

