    // "አዲስ አበባ ማስተባበሪያ ጽ/ቤት - ZCC": ["float_26", "floa_22"],
    // "ምሥራቅ አማራ ማስተባበሪያ ጽ/ቤት - ZCC": ["float_27", "floa_23"]
};

// All float fields that need to exist on every grouped row (used for init + total sum)
const ALL_FLOAT_FIELDS = Object.values(departmentMap).flat();

// -------------------------------
// DEBOUNCE HELPER
// -------------------------------
let sync_timer = null;

function debounced_sync(frm) {
    if (sync_timer) clearTimeout(sync_timer);
    sync_timer = setTimeout(() => {
        sync_timer = null;
        sync_items(frm);
    }, 300);
}

// -------------------------------
// TRIGGER SYNC
// -------------------------------
frappe.ui.form.on('Training Demand', {
    annual_procurement_demand(frm, cdt, cdn) {
        debounced_sync(frm);
    },
    department(frm, cdt, cdn) {
        debounced_sync(frm);
    }
});

// -------------------------------
// CORE FUNCTION
// -------------------------------
function sync_items(frm) {
    let demands = frm.doc.procurement_demand || [];

    // Filter only rows that have both fields set
    let valid_demands = demands.filter(d => d.annual_procurement_demand && d.department);

    if (!valid_demands.length) {
        frm.clear_table("items");
        frm.refresh_field("items");
        return;
    }

    // Load all docs first, then build grouped result once
    let promises = valid_demands.map(d =>
        new Promise(resolve => {
            frappe.model.with_doc("Training Request Format", d.annual_procurement_demand, () => {
                resolve({
                    doc: frappe.model.get_doc("Training Request Format", d.annual_procurement_demand),
                    department: d.department
                });
            });
        })
    );

    Promise.all(promises).then(results => {
        let grouped = {};

        results.forEach(({ doc, department }) => {
            if (!doc || !doc.table_4) return;

            let fields = departmentMap[department]; // [male_field, female_field]

            doc.table_4.forEach(row => {
                if (!row.training_type) return;

                let key = row.training_type;
                let male_qty = flt(row.male || 0);
                let female_qty = flt(row.female || 0);

                if (!grouped[key]) {
                    grouped[key] = {
                        item_code: key,
                        description: "",
                        total_quantity: 0,
                        market_price: 0,
                        total_price: 0,
                        remark: ""
                    };
                    // initialize all float fields to 0
                    ALL_FLOAT_FIELDS.forEach(f => { grouped[key][f] = 0; });
                }

                grouped[key].total_quantity += male_qty + female_qty;

                if (fields) {
                    let [female_field, male_field] = fields;
                    grouped[key][male_field] += male_qty;
                    grouped[key][female_field] += female_qty;
                }
            });
        });

        // Clear and repopulate ONCE after all docs are processed
        frm.clear_table("items");
        Object.values(grouped).forEach(r => frm.add_child("items", r));
        frm.refresh_field("items");
    });
}

