function fetch_employees(frm) {
    // Don't fetch until both fields are selected
    if (!frm.doc.company_branch || !frm.doc.employment_type) {
        return;
    }

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Employee",

            filters: {
                custom_branch: frm.doc.company_branch,
                employment_type: frm.doc.employment_type
            },

            fields: [
                "name",
                "employee_name"
            ],

            limit_page_length: 0
        },

        callback: function(r) {
            if (!r.message) {
                return;
            }

            // Clear existing rows
            frm.clear_table("employee_attendance_table");

            // Add employees
            r.message.forEach(function(employee) {
                let row = frm.add_child("employee_attendance_table");

                row.employee_id = employee.name;
                row.employee_name = employee.employee_name;
                row.working_days = 30;

                // Initialize absence values
                row.absent_days = 0;
                row.absent_hours = 0;
                row.absent_minutes = 0;
                row.absent_seconds = 0;
            });

            frm.refresh_field("employee_attendance_table");

            frappe.show_alert({
                message: `${r.message.length} employee(s) added`,
                indicator: "green"
            });
        }
    });
}


/*
 * Calculate Working Days
 *
 * 1 day = 8 working hours
 * 1 day = 480 minutes
 * 1 day = 28,800 seconds
 */
function calculate_working_days(row) {
    let absent_days = flt(row.absent_days);
    let absent_hours = flt(row.absent_hours);
    let absent_minutes = flt(row.absent_minutes);
    let absent_seconds = flt(row.absent_seconds);

    let absent_in_days =
        absent_days +
        (absent_hours / 8) +
        (absent_minutes / 480) +
        (absent_seconds / 28800);

    let working_days = 30 - absent_in_days;

    // Don't allow negative working days
    if (working_days < 0) {
        working_days = 0;
    }

    row.working_days = working_days;
}


