frappe.ui.form.on('Contract Work Payment Form Table', {

    unit_price: function(frm, cdt, cdn) {
        calculate_payment(frm, cdt, cdn);
    },

    qty: function(frm, cdt, cdn) {
        calculate_payment(frm, cdt, cdn);
    },

    calculate_pension: function(frm, cdt, cdn) {
        calculate_payment(frm, cdt, cdn);
    },

    calculate_income_tax: function(frm, cdt, cdn) {
        calculate_payment(frm, cdt, cdn);
    },

    form_render: function(frm, cdt, cdn) {
        calculate_payment(frm, cdt, cdn);
    }
});


function calculate_payment(frm, cdt, cdn) {

    let row = locals[cdt][cdn];

    // ==========================================
    // 1. Calculate Total Amount
    // Total Amount = Unit Price × Qty
    // ==========================================

    let unit_price = flt(row.unit_price);
    let qty = flt(row.qty);

    let total_amount = unit_price * qty;

    frappe.model.set_value(
        cdt,
        cdn,
        'total_amount',
        total_amount
    );


    // ==========================================
    // 2. Calculate Pension
    // Only if calculate_pension is checked
    // ==========================================

    if (row.calculate_pension) {

        let pension_amount = total_amount * 0.07;

        frappe.model.set_value(
            cdt,
            cdn,
            'pension_amount',
            pension_amount
        );

    } else {

        frappe.model.set_value(
            cdt,
            cdn,
            'pension_amount',
            0
        );
    }


    // ==========================================
    // 3. Calculate Income Tax
    // Only if calculate_income_tax is checked
    // ==========================================

    if (row.calculate_income_tax) {

        calculate_income_tax(
            frm,
            cdt,
            cdn,
            total_amount
        );

    } else {

        frappe.model.set_value(
            cdt,
            cdn,
            'income_tax',
            0
        );

        calculate_net_amount(
            frm,
            cdt,
            cdn
        );
    }
}


// ==========================================
// Calculate Income Tax
// ==========================================

function calculate_income_tax(
    frm,
    cdt,
    cdn,
    total_amount
) {

    frappe.call({

        method: 'frappe.client.get_list',

        args: {
            doctype: 'Employee Income Tax Slab',
            fields: ['name'],
            limit_page_length: 1
        },

        callback: function(r) {

            if (!r.message || !r.message.length) {

                frappe.msgprint(
                    __('Employee Income Tax Slab document was not found.')
                );

                frappe.model.set_value(
                    cdt,
                    cdn,
                    'income_tax',
                    0
                );

                calculate_net_amount(
                    frm,
                    cdt,
                    cdn
                );

                return;
            }


            let slab_name = r.message[0].name;


            // ==========================================
            // Get Tax Slab Document
            // ==========================================

            frappe.call({

                method: 'frappe.client.get',

                args: {
                    doctype: 'Employee Income Tax Slab',
                    name: slab_name
                },

                callback: function(res) {

                    if (!res.message) {
                        return;
                    }

                    let tax_doc = res.message;

                    let income_tax = 0;


                    // ==========================================
                    // Find Applicable Tax Slab
                    // ==========================================

                    (
                        tax_doc.employee_income_tax_slab_table || []
                    ).forEach(function(slab) {

                        let from_amount =
                            flt(slab.from_amount);

                        let to_amount =
                            flt(slab.to_amount);

                        let percent_deduction =
                            flt(slab.percent_deduction);

                        let return_amount =
                            flt(slab.return_amount);


                        if (
                            total_amount >= from_amount &&
                            total_amount <= to_amount
                        ) {

                            income_tax =
                                (total_amount *
                                    percent_deduction / 100)
                                - return_amount;
                        }

                    });


                    // ==========================================
                    // Prevent Negative Tax
                    // ==========================================

                    income_tax = Math.max(
                        income_tax,
                        0
                    );


                    // ==========================================
                    // Set Income Tax
                    // ==========================================

                    frappe.model.set_value(
                        cdt,
                        cdn,
                        'income_tax',
                        income_tax
                    );


                    // ==========================================
                    // Calculate Net Amount
                    // ==========================================

                    calculate_net_amount(
                        frm,
                        cdt,
                        cdn
                    );
                }
            });
        }
    });
}


// ==========================================
// Calculate Net Amount
// Net = Total - Pension - Income Tax
// ==========================================

function calculate_net_amount(
    frm,
    cdt,
    cdn
) {

    let row = locals[cdt][cdn];

    let total_amount =
        flt(row.total_amount);

    let pension_amount =
        flt(row.pension_amount);

    let income_tax =
        flt(row.income_tax);


    let net_amount =
        total_amount -
        pension_amount -
        income_tax;


    frappe.model.set_value(
        cdt,
        cdn,
        'net_amount',
        net_amount
    );
}

