        // 1. Find the Employee Clearance Settings record matching this Clearance Place
        const settings_list = await frappe.db.get_list('Employee Clearance Settings', {
            filters: { clearance_type: frm.doc.clearance_place },
            fields: ['name'],
            limit: 1
        });

        if (!settings_list.length) {
            frappe.msgprint(`No Employee Clearance Settings found for Clearance Place: ${frm.doc.clearance_place}`);
            return;
        }

        // 2. Fetch the full settings document (to access its child table)
        const settings_doc = await frappe.db.get_doc('Employee Clearance Settings', settings_list[0].name);

        if (!settings_doc.employee_clearance || !settings_doc.employee_clearance.length) {
            frappe.msgprint('This Clearance Place has no clearance items configured.');
            return;
        }

        // 3. Clear existing rows and repopulate from settings
        frm.clear_table('clearance_items');

        settings_doc.employee_clearance.forEach(function(item) {
            const row = frm.add_child('clearance_items');
            row.department = item.department;
            row.clearance_type = item.clearance_type;
            row.responsible_person = item.responsible_person;
            row.signa = item.signa;
            row.status = 'Pending';
            row.remarks = '';
        });

        frm.refresh_field('clearance_items');
        frappe.show_alert({ message: `${settings_doc.employee_clearance.length} clearance items populated.`, indicator: 'green' });
    }
});

