function render_questionnaire(frm, qDoc) {
    var $w = frm.fields_dict.custom_questionnaire_preview.$wrapper;

    var labelByName = {};
    (qDoc.questions || []).forEach(function (q) {
        labelByName[q.name] = q.label;
    });

    var savedByLabel = {};
    if (frm.doc.custom_questionnaire_response) {
        try {
            savedByLabel = JSON.parse(frm.doc.custom_questionnaire_response) || {};
        } catch (e) {
            savedByLabel = {};
        }
    }
    var answers = {};
    (qDoc.questions || []).forEach(function (q) {
        if (savedByLabel.hasOwnProperty(q.label)) {
            answers[q.name] = savedByLabel[q.label];
        }
    });

    var html = '<div style="border:1px solid #eee;padding:16px;border-radius:8px;margin-top:10px">';
    html += '<h4>' + frappe.utils.escape_html(qDoc.title || '') + '</h4>';
    html += '<p class="text-muted">' + frappe.utils.escape_html(qDoc.description || '') + '</p>';

    (qDoc.questions || []).forEach(function (q, i) {
        var saved = answers[q.name];

        html += '<div class="form-group" style="margin-bottom:12px">';
        html += '<label>' + (i + 1) + '. ' + frappe.utils.escape_html(q.label) +
                 (q.is_required ? ' *' : '') + '</label>';

        var opts = (q.options || '').split('\n').map(o => o.trim()).filter(Boolean);

        if (q.question_type === 'Select') {
            html += '<select class="form-control" data-field="' + q.name + '">';
            html += '<option value="">choose</option>';
            opts.forEach(o => {
                var sel = (saved === o) ? ' selected' : '';
                html += '<option value="' + o + '"' + sel + '>' + o + '</option>';
            });
            html += '</select>';
        } else if (q.question_type === 'Multi-select') {
            var savedArr = Array.isArray(saved) ? saved : [];
            opts.forEach(o => {
                var checked = savedArr.includes(o) ? ' checked' : '';
                html += '<div class="checkbox"><label><input type="checkbox" data-field="' +
                        q.name + '" value="' + o + '"' + checked + '> ' + o + '</label></div>';
            });
        } else if (q.question_type === 'Rating') {
            var max = q.max_value || 5;
            html += '<div class="rating" data-field="' + q.name + '" data-max="' + max + '">';
            for (var s = 1; s <= max; s++) {
                var filled = saved && s <= saved;
                html += '<span data-value="' + s + '" style="cursor:pointer;font-size:20px;color:' +
                        (filled ? '#fbbf24' : '#d1d5db') + '">★</span>';
            }
            html += '</div>';
        } else if (q.question_type === 'Date') {
            html += '<input type="date" class="form-control" data-field="' + q.name + '" value="' +
                    (saved || '') + '">';
        } else {
            html += '<input type="text" class="form-control" data-field="' + q.name + '" value="' +
                    frappe.utils.escape_html(saved || '') + '">';
        }

        html += '</div>';
    });

    html += '<div id="questionnaire-summary" style="margin-top:16px"></div>';
    html += '</div>';

    $w.html(html);

    function render_summary(labeled) {
        var $summary = $w.find('#questionnaire-summary');
        var keys = Object.keys(labeled);

        if (!keys.length) {
            $summary.html('');
            return;
        }

        var sHtml = '<div style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;padding:14px 16px;margin-top:8px">';
        sHtml += '<div style="font-size:13px;font-weight:600;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;margin-bottom:10px">Response Summary</div>';

        keys.forEach(function (label) {
            var val = labeled[label];
            var displayVal = Array.isArray(val) ? val.join(', ') : (val || '—');

            sHtml += '<div style="display:flex;flex-wrap:wrap;padding:6px 0;border-bottom:1px dashed #e5e7eb">';
            sHtml += '<div style="font-weight:700;color:#111827;min-width:220px;margin-right:12px">' +
                     frappe.utils.escape_html(label) + '</div>';
            sHtml += '<div style="color:#374151">' + frappe.utils.escape_html(displayVal) + '</div>';
            sHtml += '</div>';
        });

        sHtml += '</div>';
        $summary.html(sHtml);
    }

    function persist() {
        var labeled = {};
        Object.keys(answers).forEach(function (fieldName) {
            var label = labelByName[fieldName] || fieldName;
            labeled[label] = answers[fieldName];
        });
        frm.set_value('custom_questionnaire_response', JSON.stringify(labeled));
        render_summary(labeled);
    }

    // show summary immediately if answers already exist (e.g. on reload)
    if (Object.keys(savedByLabel).length) {
        render_summary(savedByLabel);
    }

    // bind inputs
    $w.find('[data-field]').on('change', function () {
        var field = $(this).data('field');
        if (this.type === 'checkbox') {
            if (!answers[field]) answers[field] = [];
            if (this.checked) answers[field].push(this.value);
            else answers[field] = answers[field].filter(v => v !== this.value);
        } else {
            answers[field] = this.value;
        }
        persist();
    });

    // bind ratings
    $w.find('.rating').each(function () {
        var $rating = $(this);
        var field = $rating.data('field');
        $rating.find('span').on('click', function () {
            var val = $(this).data('value');
            answers[field] = val;
            $rating.find('span').each(function () {
                $(this).css('color', $(this).data('value') <= val ? '#fbbf24' : '#d1d5db');
            });
            persist();
        });
    });
}

