function update_all_leave_balances(frm) {

    if (!frm.doc.employee) {
        return;
    }

    (frm.doc.annual_leave_transfer || []).forEach(row => {

        if (row.leave_type) {
            update_leave_balance(frm, row.doctype, row.name);
        }

    });
}


function update_leave_balance(frm, cdt, cdn) {

    let row = locals[cdt][cdn];

    if (!frm.doc.employee) {
        frappe.msgprint(__("Please select an Employee first."));
        return;
    }

    if (!row.leave_type) {
        return;
    }

    frappe.call({

        method: "standard.erp_solution_ethiopia_standards.doctype.annual_leave_transfer_form.annual_leave_transfer_form.get_current_leave_balance",

        args: {
            employee: frm.doc.employee,
            leave_type: row.leave_type
        },

        callback: function(r) {

            if (r.message !== undefined) {

                frappe.model.set_value(
                    cdt,
                    cdn,
                    "transfer_amount",
                    r.message
                );

                frappe.show_alert({
                    message: __("Current Leave Balance: {0}", [r.message]),
                    indicator: "green"
                });
            }

        }

    });
}

