frappe.ui.form.on('Leave Programme Table', {
    date_ec: function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        const ecDate = row.date_ec;
        if (ecDate) {
            const [day, month, year] = ecDate.split("/").map(Number);
            const [gcYear, gcMonth, gcDay] = toGC([year, month, day]);
            const gcValue = `${gcYear}-${gcMonth < 10 ? '0' : ''}${gcMonth}-${gcDay < 10 ? '0' : ''}${gcDay}`;
            frappe.model.set_value(cdt, cdn, 'from_date', gcValue);
        }
    },

    i_date_ec: function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        const ecDate = row.i_date_ec;
        if (ecDate) {
            const [day, month, year] = ecDate.split("/").map(Number);
            const [gcYear, gcMonth, gcDay] = toGC([year, month, day]);
            const gcValue = `${gcYear}-${gcMonth < 10 ? '0' : ''}${gcMonth}-${gcDay < 10 ? '0' : ''}${gcDay}`;
            frappe.model.set_value(cdt, cdn, 'to_date', gcValue);
        }
    },

    ec_date_ec: function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        const ecDate = row.ec_date_ec;
        if (ecDate) {
            const [day, month, year] = ecDate.split("/").map(Number);
            const [gcYear, gcMonth, gcDay] = toGC([year, month, day]);
            const gcValue = `${gcYear}-${gcMonth < 10 ? '0' : ''}${gcMonth}-${gcDay < 10 ? '0' : ''}${gcDay}`;
            frappe.model.set_value(cdt, cdn, 'from_date_gc', gcValue);
        }
    },

    ed_date_ec: function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        const ecDate = row.ed_date_ec;
        if (ecDate) {
            const [day, month, year] = ecDate.split("/").map(Number);
            const [gcYear, gcMonth, gcDay] = toGC([year, month, day]);
            const gcValue = `${gcYear}-${gcMonth < 10 ? '0' : ''}${gcMonth}-${gcDay < 10 ? '0' : ''}${gcDay}`;
            frappe.model.set_value(cdt, cdn, 'to_date_gc', gcValue);
        }
    },

    // Requested days = from_date -> to_date (fires once from_date/to_date are set,
    // whether via the EC converters above or picked manually).
    from_date: function(frm, cdt, cdn) {
        calculate_requested(frm, cdt, cdn);
    },
    to_date: function(frm, cdt, cdn) {
        calculate_requested(frm, cdt, cdn);
    },

    // Given days = from_date_gc -> to_date_gc
    from_date_gc: function(frm, cdt, cdn) {
        calculate_given(frm, cdt, cdn);
    },
    to_date_gc: function(frm, cdt, cdn) {
        calculate_given(frm, cdt, cdn);
    },

    // Row added/removed also changes the parent totals.
    [`${LEAVE_PROGRAMME_FIELDNAME}_add`]: function(frm) {
        calculate_totals(frm);
    },
    [`${LEAVE_PROGRAMME_FIELDNAME}_remove`]: function(frm) {
        calculate_totals(frm);
    }
});

function calculate_requested(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    if (row.from_date && row.to_date) {
        const days = frappe.datetime.get_diff(row.to_date, row.from_date) + 1;
        frappe.model.set_value(cdt, cdn, 'requested', days > 0 ? days : 0);
    } else {
        frappe.model.set_value(cdt, cdn, 'requested', 0);
    }
    calculate_totals(frm);
}

function calculate_given(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    if (row.from_date_gc && row.to_date_gc) {
        const days = frappe.datetime.get_diff(row.to_date_gc, row.from_date_gc) + 1;
        frappe.model.set_value(cdt, cdn, 'given', days > 0 ? days : 0);
    } else {
        frappe.model.set_value(cdt, cdn, 'given', 0);
    }
    calculate_totals(frm);
}

// Sums every row's requested/given onto the parent's requestedd/givenn fields.
function calculate_totals(frm) {
    let total_requested = 0;
    let total_given = 0;

    (frm.doc[LEAVE_PROGRAMME_FIELDNAME] || []).forEach(row => {
        total_requested += flt(row.requested);
        total_given += flt(row.given);
    });

    frm.set_value('requestedd', total_requested);
    frm.set_value('givenn', total_given);
}

