frappe.listview_settings['Employee Performance Template'] = {
    onload: function(listview) {
        listview.page.add_action_item(__('Prepare & Assign'), function() {
            let checked_items = listview.get_checked_items();

            if (!checked_items.length) {
                frappe.msgprint(__('Please select at least one Draft document.'));
                return;
            }

            let invalid = checked_items.filter(d => d.workflow_state !== 'Draft');
            if (invalid.length) {
                frappe.msgprint(__('Only Draft documents can be prepared. Please unselect: {0}', [invalid.map(d => d.name).join(', ')]));
                return;
            }

            let d = new frappe.ui.Dialog({
                title: __('Assign User Before Prepare'),
                size: 'large',
                fields: [{ fieldname: 'assign_html', fieldtype: 'HTML' }],
                primary_action_label: __('Prepare & Assign'),
                primary_action: function() {
                    let assignments = [];
                    let valid = true;

                    (d.assign_controls || []).forEach(function(row) {
                        let user = row.control.get_value();
                        if (!user) valid = false;
                        assignments.push({ docname: row.docname, user: user });
                    });

                    if (!valid) {
                        frappe.msgprint(__('Please select a user for every document.'));
                        return;
                    }

                    d.hide();

                    frappe.call({
                        method: 'assign_template',
                        args: {
                            doctype: listview.doctype,
                            assignments: JSON.stringify(assignments)
                        },
                        freeze: true,
                        freeze_message: __('Preparing and assigning...'),
                        callback: function(r) {
                            frappe.msgprint(__('Done: {0} document(s) processed.', [(r.message || []).length]));
                            listview.refresh();
                        }
                    });
                }
            });

            let wrapper = d.get_field('assign_html').$wrapper;
            d.assign_controls = [];

            checked_items.forEach(function(doc, i) {
                let row_wrapper = $(
                    '<div class="row" style="margin-bottom:12px; padding-bottom:8px; border-bottom:1px solid #eee;">' +
                        '<div class="col-sm-6" style="padding-top:6px;"><strong>' + frappe.utils.escape_html(doc.name) + '</strong></div>' +
                        '<div class="col-sm-6 assign-col-' + i + '"></div>' +
                    '</div>'
                ).appendTo(wrapper);

                let control = frappe.ui.form.make_control({
                    parent: row_wrapper.find('.assign-col-' + i),
                    df: {
                        fieldtype: 'Link',
                        fieldname: 'user_' + i,
                        options: 'User',
                        label: __('Assign To'),
                        reqd: 1
                    },
                    render_input: true
                });
                control.refresh();

                d.assign_controls.push({ docname: doc.name, control: control });
            });

            d.show();
        });
    }
};

