function convert_existing_dates(frm) {
    if (!frm.doc.holidays) return;

    let changed = false;
    frm.doc.holidays.forEach(row => {
        if (row.holiday_date && !row.custom_date_ec) {
            const [year, month, day] = toEC(row.holiday_date.split("-").map(Number));
            row.custom_date_ec = `${day < 10 ? '0' : ''}${day}/${month < 10 ? '0' : ''}${month}/${year}`;
            changed = true;
        }
    });

    if (changed) {
        frm.refresh_field("holidays");
    }
}


